/* ============================================================
   max-width: 991px — .mission-sec22-gridboxes: 2 columns
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding-top: 0;
    padding-bottom: 40px;
  }

  .header {
    margin-bottom: 40px;
  }

  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section {
    padding-top: 0;
    padding-bottom: 40px;
  }

  .heading {
    font-size: 28px;
  }

  .header {
    margin-bottom: 40px;
  }
}

/* ============================================================
   max-width: 479px — .mission-sec22-gridboxes: 1 column
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-bottom: 40px;
  }

  .header {
    margin-bottom: 20px;
  }

  .grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .card {
    padding: 24px 20px;
  }

  .heading {
    font-size: 24px;
  }

  .subtitle {
    font-size: 15px;
  }
}

